<!doctype html>
<html lang="zh-CN">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RISCP POS</title><style>body{font-family:system-ui;margin:0;background:#f5f6f8;color:#20242a}.top{padding:16px 24px;background:#111827;color:#fff}.layout{display:grid;grid-template-columns:180px 1fr 340px;gap:16px;padding:16px}.panel{background:#fff;border-radius:12px;padding:16px}.item{padding:14px;border:1px solid #e5e7eb;border-radius:10px;margin-bottom:10px;cursor:pointer}.cart-row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #eee}.btn{width:100%;padding:13px;border:0;border-radius:8px;background:#111827;color:#fff;cursor:pointer}.hint{font-size:12px;color:#6b7280}.input{width:100%;box-sizing:border-box;padding:10px;margin:6px 0 12px;border:1px solid #d1d5db;border-radius:8px}</style></head>
<body><div class="top"><strong>RISCP POS</strong> · 餐饮门店</div><main class="layout"><section class="panel"><h3>订单</h3><label class="hint">Tenant ID</label><input id="tenant" class="input" placeholder="UUID"><label class="hint">Store ID</label><input id="store" class="input" placeholder="UUID"><label class="hint">Table ID（可选）</label><input id="table" class="input" placeholder="UUID"><h3>分类</h3><div>全部</div><div>热菜</div><div>主食</div><div>饮品</div></section><section class="panel"><h3>菜品</h3><div id="items"></div></section><section class="panel"><h3>购物车</h3><div id="cart"></div><hr><h2 id="total">¥0.00</h2><button class="btn" onclick="submitOrder()">提交订单</button><p id="result" class="hint"></p></section></main><script>const items=[{id:'demo-1',name:'招牌套餐',price:38},{id:'demo-2',name:'牛肉面',price:22},{id:'demo-3',name:'鲜榨果汁',price:15}];const cart=[];function render(){document.querySelector('#items').innerHTML=items.map(x=>`<div class="item" onclick="add('${x.id}')"><strong>${x.name}</strong><br>¥${x.price.toFixed(2)}</div>`).join('');document.querySelector('#cart').innerHTML=cart.map(x=>`<div class="cart-row"><span>${x.name} × ${x.qty}</span><span>¥${(x.price*x.qty).toFixed(2)}</span></div>`).join('')||'<div>暂未选择菜品</div>';document.querySelector('#total').textContent='¥'+cart.reduce((s,x)=>s+x.price*x.qty,0).toFixed(2)}function add(id){const x=items.find(i=>i.id===id),row=cart.find(i=>i.id===id);if(row)row.qty++;else cart.push({...x,qty:1});render()}async function submitOrder(){if(!cart.length)return alert('请先选择菜品');const tenant_id=document.querySelector('#tenant').value,store_id=document.querySelector('#store').value;if(!tenant_id||!store_id)return alert('请填写 Tenant ID 和 Store ID');const body={tenant_id,store_id,table_id:document.querySelector('#table').value||null,order_no:'POS-'+Date.now(),items:cart.map(x=>({sku_id:x.id,quantity:x.qty,unit_price:x.price}))};const r=await fetch('/api/v1/restaurant/orders',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(body)});const data=await r.json();document.querySelector('#result').textContent=r.ok?'订单已创建：'+data.order_id:'创建失败：'+(data.message||JSON.stringify(data));}render();</script></body></html>
